import{z as o,x as i,o as t,c as d,q as A,j as n,D as B,d as e,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"利率债市场","description":"","frontmatter":{"title":"利率债市场","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-rates-market.md","filePath":"quant/cn-rates-market.md","lastUpdated":1791413859000}'),p={name:"quant/cn-rates-market.md"};function C(u,a,D,m,h,c){const r=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="利率债市场" tabindex="-1">利率债市场 <a class="header-anchor" href="#利率债市场" aria-label="Permalink to &quot;利率债市场&quot;">​</a></h1><div class="epigraph"><p>中国利率债的定价锚是国债与政策性金融债的曲线，交易主场在银行间。量化要跟踪的是曲线因子、发行供给与流动性分层，而不是把股票换手因子换一个 ticker。</p><footer>—— 财政部国债发行与中国人民银行公开市场操作相关制度；中金所国债期货合约；对照 Tuckman 对利率债相对价值的处理；[国债期货 CTD](/quant/cn-tf-ctd)</footer></div><p><a href="/quant/cn-sentiment-indicators">上一课</a>停在股票情绪。本课把中国进阶接到<strong>利率债</strong>：国债、地方政府债、政策性银行债（国开、口行、农发）。下一课专门写银行间与交易所两个场所的分割。本课先写产品、曲线与期货对冲，不把<a href="/quant/lob-structure">LOB</a> 的股票十档当成银行间询价的深度。固收 RV 与 repo 课已给一般机制，这里钉中国曲线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票因子宇宙是竞价连续盘。利率债大量成交在银行间一对多询价与经纪商系统，价格是对话的结果，透明度与股票 TAQ 不同。中债估值、中证估值是模型价，不等于可成交。<span class="marginnote">先解释「久期」这个词：它是债券价格对利率的灵敏度，相当于利率风险温度计。数字例子：修正久期 5 的债券，利率上行 10 个基点（0.10%），价格大约跌 5 × 0.10% = 0.5%，100 元的债券跌约 5 毛钱。久期越长，利率动一点价格晃得越厉害。</span>问题是：久期、曲线陡峭、国开–国债利差（隐含税收与流动性）如何在点-in-time 估值与可成交报价之间切换。用估值收益当可实现收益，会高估交易策略，尤其在压力日估值平滑、成交稀疏。</p>',5)),(t(),n(s,null,{default:B(()=>[l(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAL%5B%22%E4%B8%AD%E5%80%BA%20%2F%20%E4%B8%AD%E8%AF%81%E4%BC%B0%E5%80%BC%3A%20%E6%A8%A1%E5%9E%8B%E4%BB%B7%22%5D%20--%3E%20GAP%7B%22%E4%BC%B0%E5%80%BC%E4%B8%8E%E5%8F%AF%E6%88%90%E4%BA%A4%E4%BB%B7%22%7D%0A%20%20DEAL%5B%22%E7%BB%8F%E7%BA%AA%E5%95%86%E6%8A%A5%E4%BB%B7%E4%B8%8E%E6%88%90%E4%BA%A4%3A%20%E5%8F%AF%E5%AE%9E%E7%8E%B0%E4%BB%B7%22%5D%20--%3E%20GAP%0A%20%20GAP%20--%3E%7C%22%E5%B9%B3%E9%9D%99%E6%97%A5%22%7C%20NEAR%5B%22%E4%B8%A4%E8%80%85%E6%8E%A5%E8%BF%91%2C%20%E5%B7%AE%E5%BC%82%E5%8F%AF%E5%BF%BD%E7%95%A5%22%5D%0A%20%20GAP%20--%3E%7C%22%E5%8E%8B%E5%8A%9B%E6%97%A5%22%7C%20FAR%5B%22%E4%BC%B0%E5%80%BC%E5%B9%B3%E6%BB%91%2C%20%E6%88%90%E4%BA%A4%E7%A8%80%E7%96%8F%22%5D%0A%20%20FAR%20--%3E%20RISK%5B%22%E6%8C%89%E4%BC%B0%E5%80%BC%E5%9B%9E%E6%B5%8B%E4%BC%9A%E9%AB%98%E4%BC%B0%E7%AD%96%E7%95%A5%22%5D%0A%20%20NEAR%20--%3E%20SRC%5B%22%E4%BB%8D%E9%A1%BB%E5%A3%B0%E6%98%8E%E4%BC%B0%E5%80%BC%E6%BA%90%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20RISK%20--%3E%20SRC%0A%20%20SRC%20--%3E%20PIT%5B%22%E5%9B%9E%E6%B5%8B%E5%8F%AA%E7%94%A8%E5%BD%93%E6%97%B6%E7%89%88%E6%9C%AC%E7%9A%84%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>供给：财政部与政策性银行的发行节奏改变特定券的特殊性与曲线。地方债有财政与置换节奏。量化「利率债动量」若忽略发行日历，会把供给冲击当价格信号。国债期货提供可保证金的久期，CTD 与基差见已有课；对冲成本同样含保证金与交割期权，不是 beta=1。</p><h3 id="流动性分层" tabindex="-1">流动性分层 <a class="header-anchor" href="#流动性分层" aria-label="Permalink to &quot;流动性分层&quot;">​</a></h3><p>新券、关键期限、政策金融债的活跃券与老券、奇异期限差很大。容量按活跃券可成交量估。<span class="marginnote">直觉类比：新发国债就像最新款手机，二手市场里大家都只想交易它，报价密、点差窄；同期限的老券像上一代机型，性能没差多少却没什么人问津，想卖就得让价。所以「活跃券溢价」主要反映的是交易便利，不是信用或利率预期的差别。</span>把全部中债财富指数成分当可交易宇宙，冲击被低估。repo 融资是杠杆管道，haircut 与银行间流动性（DR007 等）进入成本，见<a href="/quant/repo-funding">回购</a>。</p><p><span class="marginnote">货币政策与公开市场操作改变短端；曲线长端还受期限溢价与供求。把所有收益归因于「降准」一句，曲线交易无法记账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>曲线：用可成交报价或可靠经纪商报价构建关键期限，声明估值源。因子：水平、斜率、蝶式，对冲用国债期货或活跃券篮子，报告 CTD 切换。事件：发行、缴款、降准、MLF、国债期货交割月。回测用当时估值版本，避免用今日中债曲线回填。与股票组合的宏观对冲：利率债久期对冲的是贴现率一截，不是股权风险溢价。</p><p>信用不在本课：中票、公司债、城投是信用利差，场所仍常在银行间，但风险源不同，勿与利率债因子混池。<span class="marginnote">常见误区：把中债估值当成「我能卖到的价格」。估值是第三方模型按附近成交与曲线推出来的参考价，真要出手时对手方给的报价可能低不少——持仓越偏门、市场越紧张，这个差距越大。所以估值适合记净值和算风险，不适合直接当策略的可实现收益。</span></p><h3 id="与股票量化的接口" tabindex="-1">与股票量化的接口 <a class="header-anchor" href="#与股票量化的接口" aria-label="Permalink to &quot;与股票量化的接口&quot;">​</a></h3><p>股债风险平价、宏观风险平价类产品同时持有利率债与股票。A 股涨跌停不直接限制国债，但资金与赎回在同一日要现金：股票缺腿时可能被迫卖债。跨资产容量是联合的，见实盘容量课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>利率债收益来自票息、资本利得（曲线移动）与融资。特殊性使 CTD 与活跃券偏离估值曲线。银行体系是主要持有人，监管与资本（若适用）改变需求弹性，利差可以因「谁能持有」而变，不必有新的宏观信息。这与国际银行持有国债的文献同方向，制度细节是中国银行间与政策金融债税收。</p><p>期货把久期杠杆化，2015 年之后国债期货流动性逐步发展，样本须分段。用美债期货的经验系数填中国 CTD，转换因子与可交割篮不同。</p>',12)),(t(),n(s,null,{default:B(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Iss%5B%22%E5%9B%BD%E5%80%BA%E4%B8%8E%E6%94%BF%E9%87%91%E5%80%BA%E5%8F%91%E8%A1%8C%22%5D%20--%3E%20Curve%5B%22%E5%85%B3%E9%94%AE%E6%9C%9F%E9%99%90%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20OMO%5B%22%E5%85%AC%E5%BC%80%E5%B8%82%E5%9C%BA%E4%B8%8E%E7%9F%AD%E7%AB%AF%E5%88%A9%E7%8E%87%22%5D%20--%3E%20Curve%0A%20%20Curve%20--%3E%20Fut%5B%22%E5%9B%BD%E5%80%BA%E6%9C%9F%E8%B4%A7%20CTD%22%5D%0A%20%20Liq%5B%22%E6%B4%BB%E8%B7%83%E5%88%B8%20vs%20%E8%80%81%E5%88%B8%22%5D%20--%3E%20Cap%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E5%AE%B9%E9%87%8F%22%5D%0A%20%20Repo%5B%22%E9%93%B6%E8%A1%8C%E9%97%B4%E5%9B%9E%E8%B4%AD%22%5D%20--%3E%20Lev%5B%22%E6%9D%A0%E6%9D%86%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"边界",tabindex:"-1"},[e("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=E("p",null,"不提供利用非公开招标信息或操纵发行的方法。地方债、储蓄国债、央行票据各有规则。本课不预测货币政策。外汇与中美利差是宏观对象，本课只要求曲线数据契约诚实。",-1)),a[6]||(a[6]=E("h2",{id:"小结",tabindex:"-1"},[e("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=E("ul",null,[E("li",null,"中国利率债以国债与政金债曲线为锚，交易与估值源必须声明。"),E("li",null,"发行供给与流动性分层决定容量；期货对冲看 CTD。"),E("li",null,"估值收益 ≠ 可成交收益，压力日尤其。"),E("li",null,"出处：财政部与国开发行制度；中金所国债期货；Tuckman；本栏 CTD 课。")],-1))])}const T=o(p,[["render",C]]);export{F as __pageData,T as default};
